FILMS.push(
/* ---------- SECONDE s07 : procréation ---------- */
{ id: 's07', level: 'seconde', ord: 7, title: 'Procréation et sexualité humaine', clips: [
 { n: 1, title: 'Rappel : appareils reproducteurs et gamètes', cues: [
  { say: "Pour avoir un enfant, il faut la rencontre de deux cellules reproductrices, les gamètes : un spermatozoïde, produit par l'homme, et un ovule, produit par la femme. Cette rencontre s'appelle la fécondation.",
    draw: a => `<circle cx="300" cy="240" r="110" fill="${C.mom}" fill-opacity=".25" stroke="${C.mom}" stroke-width="4"/><circle cx="300" cy="240" r="30" fill="${C.mom}" fill-opacity=".6"/>` + `<ellipse cx="110" cy="240" rx="22" ry="15" fill="${C.dad}"/><path d="M88 240 C 60 220, 50 260, 20 240" stroke="${C.dad}" stroke-width="4" fill="none"/>` + arrow(140, 240, 180, 240, a) + T(80, 300, 'spermatozoïde', { fs: 18 }) + T(300, 390, 'ovule', { fs: 20 }) + T(250, 460, 'fécondation', { fs: 24, w: 800, c: a }) },
  { say: "Chez l'homme, les spermatozoïdes sont fabriqués en continu, à partir de la puberté, dans les testicules. Ils sont ensuite transportés par les spermiductes, et mélangés à des liquides produits par des glandes, comme la prostate, pour former le sperme.",
    draw: a => `<ellipse cx="170" cy="340" rx="45" ry="60" fill="${C.dad}" fill-opacity=".35" stroke="${C.dad}" stroke-width="4"/><ellipse cx="330" cy="340" rx="45" ry="60" fill="${C.dad}" fill-opacity=".35" stroke="${C.dad}" stroke-width="4"/><path d="M170 280 C 170 180, 230 160, 250 140 M330 280 C 330 180, 270 160, 250 140 M250 140 V60" stroke="${C.ink}" stroke-width="6" fill="none"/><ellipse cx="250" cy="150" rx="34" ry="24" fill="${C.T}" opacity=".8"/>` + T(250, 440, 'testicules', { fs: 20 }) + pointer(410, 200, 330, 220, 'spermiducte', { fs: 18 }) + pointer(420, 120, 284, 150, 'prostate', { fs: 18 }) },
  { say: "Chez la femme, les ovaires contiennent des follicules, qui renferment chacun un ovocyte. À partir de la puberté, environ une fois par mois, un ovocyte est libéré : c'est l'ovulation. Il est capté par la trompe, où peut avoir lieu la fécondation. L'embryon s'implante ensuite dans l'utérus.",
    draw: a => `<path d="M190 200 Q250 170 310 200 L300 330 Q250 360 200 330Z" fill="${C.mom}" fill-opacity=".3" stroke="${C.mom}" stroke-width="4"/><path d="M200 210 C 150 180, 120 190, 100 230 M300 210 C 350 180, 380 190, 400 230" stroke="${C.mom}" stroke-width="8" fill="none"/><ellipse cx="95" cy="270" rx="34" ry="24" fill="${C.T}" fill-opacity=".5" stroke="${C.T}" stroke-width="3"/><ellipse cx="405" cy="270" rx="34" ry="24" fill="${C.T}" fill-opacity=".5" stroke="${C.T}" stroke-width="3"/><rect x="235" y="350" width="30" height="70" rx="10" fill="${C.mom}" fill-opacity=".4"/>` + T(250, 280, 'utérus', { fs: 20 }) + T(95, 330, 'ovaire', { fs: 18 }) + T(130, 160, 'trompe', { fs: 18 }) + T(250, 460, 'vagin', { fs: 18, c: C.mut }) },
  { say: "La fécondation produit une cellule-œuf. En se divisant, elle donne un embryon, qui se développe pendant environ neuf mois dans l'utérus, nourri par le placenta.",
    draw: a => cell(80, 240, 40, a) + arrow(130, 240, 170, 240, a) + cell(220, 240, 40, a, `<circle cx="210" cy="230" r="14" fill="${a}" fill-opacity=".5"/><circle cx="232" cy="230" r="14" fill="${a}" fill-opacity=".5"/><circle cx="210" cy="252" r="14" fill="${a}" fill-opacity=".5"/><circle cx="232" cy="252" r="14" fill="${a}" fill-opacity=".5"/>`) + arrow(270, 240, 310, 240, a) + `<circle cx="390" cy="240" r="70" fill="${C.mom}" fill-opacity=".2" stroke="${C.mom}" stroke-width="4"/><path d="M370 210 C 400 190, 430 220, 415 250 C 405 280, 370 280, 365 255 C 345 250, 350 220, 370 210Z" fill="${C.mom}" opacity=".7"/>` + T(80, 310, 'cellule-œuf', { fs: 17 }) + T(220, 310, 'embryon', { fs: 17 }) + T(390, 340, '≈ 9 mois', { fs: 18 }) },
  { sci: true, say: "En science : les gamètes sont produits par les gonades : les testicules chez l'homme, en continu à partir de la puberté, et les ovaires chez la femme, de façon cyclique. La fécondation, dans la trompe, forme une cellule-œuf, qui se développe en embryon puis en fœtus dans l'utérus.",
    rows: [['Gamètes', 'spermatozoïdes et ovocytes'], ['Testicules', 'production continue dès la puberté'], ['Ovaires', 'un ovocyte libéré par cycle'], ['Fécondation', 'dans la trompe → cellule-œuf'], ['Grossesse', 'développement dans l’utérus']] }
 ]},
 { n: 2, title: 'Puberté, hormones et cycle', cues: [
  { say: "À la puberté, le corps change : les organes reproducteurs deviennent fonctionnels, et les caractères sexuels secondaires apparaissent, comme la pilosité, la mue de la voix chez les garçons, ou le développement des seins chez les filles. Ces changements sont commandés par des hormones.",
    draw: a => person(150, 280, 1.5, C.dad) + person(350, 280, 1.5, C.mom) + T(250, 480, 'commandés par des hormones', { fs: 22, c: a }) },
  { say: "Une hormone est une molécule fabriquée par une glande, transportée par le sang, et qui agit sur des cellules cibles éloignées. Tout part du cerveau : l'hypothalamus et l'hypophyse envoient des hormones qui stimulent les testicules ou les ovaires.",
    draw: a => head(250, 150, 1, C.mut) + `<circle cx="260" cy="130" r="14" fill="${a}"/>` + T(390, 110, 'hypothalamus', { fs: 17, a: 'start', extra: 'dx="-110"' }) + arrow(260, 260, 260, 340, a) + T(270, 300, 'hormones dans le sang', { fs: 17, a: 'start', c: C.mut }) + box(180, 350, 160, 60, 'gonades', a) },
  { say: "En réponse, les testicules produisent de la testostérone, et les ovaires produisent des œstrogènes et de la progestérone. Ce sont ces hormones sexuelles qui font apparaître les caractères sexuels secondaires.",
    draw: a => box(40, 120, 190, 70, 'testicules', C.dad) + arrow(135, 200, 135, 260, C.dad) + pill(135, 290, 190, 'testostérone', C.dad) + box(270, 120, 190, 70, 'ovaires', C.mom) + arrow(365, 200, 365, 260, C.mom) + pill(365, 290, 180, 'œstrogènes', C.mom) + pill(365, 350, 180, 'progestérone', C.mom) },
  { say: "Chez la femme, le fonctionnement est cyclique. Un cycle dure environ vingt-huit jours. Il commence par les règles, et l'ovulation a lieu vers le quatorzième jour. Pendant ce temps, la muqueuse de l'utérus s'épaissit pour accueillir un éventuel embryon. Sans fécondation, elle se détruit : ce sont les règles suivantes.",
    draw: a => `<line x1="40" y1="300" x2="460" y2="300" stroke="${C.mut}" stroke-width="3"/>` + [0, 7, 14, 21, 28].map(d => `<line x1="${40 + d * 15}" y1="295" x2="${40 + d * 15}" y2="310" stroke="${C.mut}" stroke-width="3"/>` + T(40 + d * 15, 335, 'J' + d, { fs: 16, c: C.mut })).join('') + `<rect x="40" y="250" width="75" height="40" rx="8" fill="${C.bad}" opacity=".8"/>` + T(77, 240, 'règles', { fs: 17, c: C.bad }) + `<circle cx="250" cy="200" r="20" fill="${C.T}"/>` + T(250, 160, 'ovulation', { fs: 18, c: C.T }) + `<path d="M115 280 C 200 270, 300 220, 460 210" stroke="${C.mom}" stroke-width="6" fill="none"/>` + T(380, 190, 'muqueuse', { fs: 17, c: C.mom }) },
  { sci: true, say: "En science : la puberté est déclenchée par l'hypothalamus et l'hypophyse, dont les hormones stimulent les gonades. Les testicules sécrètent la testostérone, les ovaires les œstrogènes et la progestérone. Ces hormones agissent par voie sanguine sur des cellules cibles. Chez la femme, le fonctionnement des ovaires et de l'utérus est cyclique, avec une ovulation par cycle d'environ vingt-huit jours.",
    rows: [['Hormone', 'messager transporté par le sang'], ['Commande', 'hypothalamus et hypophyse'], ['Homme', 'testostérone, production continue'], ['Femme', 'œstrogènes, progestérone, cycle ≈ 28 j'], ['Ovulation', 'vers le 14e jour du cycle']] }
 ]},
 { n: 3, title: 'Maîtriser sa fécondité et se protéger', cues: [
  { say: "Comprendre les hormones permet de maîtriser sa fécondité. La pilule contraceptive contient des hormones de synthèse proches de celles des ovaires. En agissant sur le cerveau, elles bloquent l'ovulation : sans ovocyte, pas de fécondation possible.",
    draw: a => head(130, 170, .8, C.mut) + `<circle cx="140" cy="155" r="12" fill="${a}"/>` + pill(350, 150, 140, 'pilule', a) + arrow(280, 150, 200, 150, a) + T(240, 130, 'freine', { fs: 16, c: a }) + `<ellipse cx="250" cy="360" rx="50" ry="34" fill="${C.T}" fill-opacity=".3" stroke="${C.T}" stroke-width="3"/>` + T(250, 430, 'pas d’ovulation', { fs: 22, c: C.bad }) },
  { say: "Il existe d'autres moyens de contraception : le préservatif, le stérilet, ou l'implant. La contraception d'urgence, à prendre le plus tôt possible après un rapport non protégé, peut empêcher une grossesse non désirée.",
    draw: a => ['préservatif', 'stérilet', 'implant', 'contraception d’urgence'].map((t, i) => box(60, 90 + i * 90, 380, 64, t, a, { fs: 21 })).join('') },
  { say: "Le préservatif est le seul moyen de contraception qui protège aussi des infections sexuellement transmissibles, comme le VIH, la chlamydia ou le papillomavirus. Un dépistage permet de les détecter et de les traiter, et un vaccin protège contre le papillomavirus.",
    draw: a => `<path d="M250 80 L380 130 V250 C 380 340, 310 400, 250 430 C 190 400, 120 340, 120 250 V130Z" fill="${C.ok}" fill-opacity=".15" stroke="${C.ok}" stroke-width="5"/>` + virus(250, 240, 1.2, C.G) + `<line x1="190" y1="300" x2="310" y2="180" stroke="${C.bad}" stroke-width="7"/>` + T(250, 480, 'préservatif : protège des IST', { fs: 21, c: C.ok }) },
  { say: "Enfin, quand un couple n'arrive pas à avoir d'enfant, la médecine peut l'aider : c'est l'assistance médicale à la procréation. Par exemple, avec la fécondation in vitro, la rencontre des gamètes se fait au laboratoire, puis l'embryon est placé dans l'utérus.",
    draw: a => `<circle cx="250" cy="220" r="120" fill="none" stroke="${C.ink}" stroke-width="5"/>` + `<circle cx="250" cy="220" r="40" fill="${C.mom}" fill-opacity=".5"/>` + `<ellipse cx="170" cy="200" rx="14" ry="10" fill="${C.dad}"/><path d="M156 200 l-30 -10" stroke="${C.dad}" stroke-width="3"/>` + T(250, 380, 'fécondation in vitro', { fs: 22, c: a }) + T(250, 410, '(au laboratoire)', { fs: 18, c: C.mut }) },
  { sci: true, say: "En science : les contraceptifs hormonaux, comme la pilule, empêchent l'ovulation en agissant sur l'hypothalamus et l'hypophyse. Le préservatif est le seul moyen qui protège aussi des infections sexuellement transmissibles. Le dépistage et la vaccination, contre le papillomavirus par exemple, font partie de la prévention. L'assistance médicale à la procréation, comme la fécondation in vitro, aide les couples infertiles.",
    rows: [['Pilule', 'hormones de synthèse : pas d’ovulation'], ['Autres', 'préservatif, stérilet, implant, urgence'], ['IST', 'préservatif, dépistage, vaccin HPV'], ['AMP', 'ex. fécondation in vitro']] }
 ]}
]},
/* ---------- SECONDE s08 : microorganismes ---------- */
{ id: 's08', level: 'seconde', ord: 8, title: 'Microorganismes et santé', clips: [
 { n: 1, title: 'Rappel : le monde microbien', cues: [
  { say: "Les microorganismes sont des êtres vivants trop petits pour être vus à l'œil nu. On les observe au microscope. Ce sont surtout des bactéries, des levures et d'autres champignons microscopiques. Les virus, eux, ne sont pas des cellules, mais on les étudie avec eux.",
    draw: a => bacterium(120, 160, .9, C.C) + T(120, 230, 'bactérie', { fs: 18 }) + `<circle cx="370" cy="160" r="42" fill="${C.T}" fill-opacity=".35" stroke="${C.T}" stroke-width="4"/><circle cx="408" cy="128" r="18" fill="${C.T}" fill-opacity=".35" stroke="${C.T}" stroke-width="3"/>` + T(370, 230, 'levure', { fs: 18 }) + virus(250, 360, 1.3) + T(250, 450, 'virus (pas une cellule)', { fs: 18 }) },
  { say: "Pour se rendre compte des tailles : une cellule humaine mesure environ vingt micromètres, une bactérie environ deux micromètres, et un virus environ cent nanomètres, soit vingt fois plus petit qu'une bactérie. Un micromètre, c'est un millième de millimètre.",
    draw: a => `<circle cx="160" cy="240" r="130" fill="${a}" fill-opacity=".12" stroke="${a}" stroke-width="4"/>` + T(160, 400, 'cellule ≈ 20 µm', { fs: 20 }) + bacterium(360, 240, .25, C.C, { dna: false }) + T(360, 290, 'bactérie ≈ 2 µm', { fs: 18 }) + `<circle cx="440" cy="240" r="2" fill="${C.G}"/>` + T(440, 330, 'virus ≈ 0,1 µm', { fs: 16, c: C.G }) },
  { say: "Les microorganismes sont partout : dans l'air, l'eau, le sol, et sur nous. Notre corps héberge des milliers de milliards de bactéries, surtout dans l'intestin. Cet ensemble s'appelle le microbiote. La grande majorité de ces microbes ne nous rendent pas malades.",
    draw: a => person(250, 270, 1.8, C.mut) + (() => { let s = ''; for (let i = 0; i < 22; i++) s += bacterium(205 + (i % 6) * 18, 250 + Math.floor(i / 6) * 16, .12, C.C, { dna: false, rot: i * 40 }); return s; })() + pointer(380, 160, 280, 260, 'microbiote intestinal', { fs: 18 }) },
  { sci: true, say: "En science : les microorganismes regroupent des êtres vivants microscopiques, comme les bactéries, les levures et d'autres champignons. Les virus ne sont pas des cellules : ils ne peuvent se multiplier qu'à l'intérieur d'une cellule. L'ensemble des microorganismes qui vivent dans et sur notre corps forme le microbiote, composé surtout de bactéries.",
    rows: [['Microorganismes', 'bactéries, levures, champignons'], ['Tailles', 'cellule 20 µm, bactérie 2 µm, virus 0,1 µm'], ['Virus', 'pas une cellule, se multiplie dans une cellule'], ['Microbiote', 'microbes qui vivent en nous, surtout l’intestin']] }
 ]},
 { n: 2, title: 'Le microbiote, un allié', cues: [
  { say: "Le microbiote intestinal nous rend de nombreux services. Ses bactéries digèrent une partie des fibres alimentaires que nous ne savons pas digérer, et elles produisent certaines vitamines.",
    draw: a => `<path d="M140 120 C 140 80, 360 80, 360 120 C 360 160, 140 160, 140 200 C 140 240, 360 240, 360 280 C 360 320, 140 320, 140 360" fill="none" stroke="${C.mom}" stroke-width="30" stroke-linecap="round" opacity=".5"/>` + (() => { let s = ''; for (let i = 0; i < 14; i++) s += bacterium(150 + (i * 53) % 210, 120 + (i * 37) % 240, .14, C.C, { dna: false, rot: i * 30 }); return s; })() + T(250, 430, 'digère des fibres, produit des vitamines', { fs: 20, c: a }) },
  { say: "Il nous protège aussi. En occupant toute la place, les bonnes bactéries empêchent les bactéries dangereuses de s'installer. Et il aide notre système immunitaire à bien fonctionner.",
    draw: a => [0, 1, 2, 3, 4, 5, 6, 7].map(i => bacterium(80 + (i % 4) * 100, 160 + Math.floor(i / 4) * 90, .45, C.C, { dna: false })).join('') + bacterium(250, 400, .5, C.bad, { dna: false }) + T(380, 405, 'pas de place', { fs: 20, c: C.bad, a: 'start', extra: 'dx="-60"' }) },
  { say: "Ce microbiote se forme dès la naissance, et il dépend de notre alimentation et de notre mode de vie. Une alimentation variée, riche en fibres, le favorise. À l'inverse, des antibiotiques pris sans nécessité peuvent le déséquilibrer.",
    draw: a => box(60, 120, 170, 70, 'fibres, variété', C.ok) + T(145, 230, 'favorise', { fs: 18, c: C.ok }) + box(270, 120, 170, 70, 'antibiotiques', C.bad) + T(355, 230, 'déséquilibre', { fs: 18, c: C.bad }) },
  { sci: true, say: "En science : le microbiote intestinal participe à la digestion, à la production de vitamines et à la protection contre les microorganismes pathogènes, notamment en occupant leur place. Il contribue aussi au bon fonctionnement du système immunitaire. Sa composition dépend de l'histoire de chacun, de l'alimentation et des médicaments.",
    rows: [['Rôles', 'digestion des fibres, vitamines'], ['Protection', 'occupe la place des pathogènes'], ['Immunité', 'aide son bon fonctionnement'], ['Varie selon', 'naissance, alimentation, médicaments']] }
 ]},
 { n: 3, title: 'Agents pathogènes et prévention', cues: [
  { say: "Certains microorganismes, dits pathogènes, provoquent des maladies. Par exemple, une bactérie cause la tuberculose, et un virus cause la grippe. Ils peuvent se transmettre par l'air, par contact, par l'eau ou l'alimentation, ou par voie sexuelle.",
    draw: a => person(130, 280, 1.4, C.mut) + person(370, 280, 1.4, C.mut) + [0, 1, 2, 3].map(i => virus(210 + i * 28, 210 + (i % 2) * 20, .35)).join('') + T(250, 470, 'transmission', { fs: 22, c: a }) },
  { say: "Contre ces maladies, il existe des gestes simples : se laver les mains, tousser dans son coude, cuire les aliments, et utiliser des préservatifs. La vaccination protège aussi, en préparant notre système immunitaire à reconnaître un microbe avant de le rencontrer.",
    draw: a => ['se laver les mains', 'tousser dans son coude', 'cuire les aliments', 'vaccination'].map((t, i) => `<circle cx="80" cy="${120 + i * 85}" r="14" fill="${C.ok}"/>` + T(110, 127 + i * 85, t, { a: 'start', fs: 22 })).join('') },
  { say: "Contre les bactéries, les médecins utilisent des antibiotiques. Attention : les antibiotiques ne servent à rien contre les virus. Et à force de les utiliser, des bactéries résistantes apparaissent et se multiplient. C'est pour cela qu'il faut les prendre uniquement quand le médecin les prescrit.",
    draw: a => pill(130, 140, 180, 'antibiotique', a) + arrow(130, 175, 130, 230, C.ok) + bacterium(130, 290, .6, C.C) + `<line x1="90" y1="330" x2="170" y2="250" stroke="${C.bad}" stroke-width="5"/>` + T(130, 360, 'bactérie : efficace', { fs: 17, c: C.ok }) + arrow(370, 175, 370, 230, C.bad) + virus(370, 290, 1) + pill(370, 140, 180, 'antibiotique', a) + T(370, 360, 'virus : inutile', { fs: 17, c: C.bad }) },
  { sci: true, say: "En science : les agents pathogènes sont des microorganismes qui provoquent des maladies. On limite leur transmission par l'hygiène, et on s'en protège par la vaccination. Les antibiotiques tuent les bactéries ou bloquent leur multiplication, mais ils sont sans effet sur les virus. Leur usage excessif sélectionne des bactéries résistantes, ce qui est aujourd'hui un grand enjeu de santé publique.",
    rows: [['Pathogène', 'microbe qui provoque une maladie'], ['Prévention', 'hygiène, vaccination'], ['Antibiotiques', 'contre les bactéries, pas les virus'], ['Antibiorésistance', 'sélection par usage excessif']] }
 ]}
]},
/* ---------- PREMIÈRE p04 : immunité ---------- */
{ id: 'p04', level: 'premiere', ord: 9, title: 'Le système immunitaire', clips: [
 { n: 1, title: "L'immunité innée", cues: [
  { say: "Rappel : notre corps est sans cesse exposé à des microorganismes. La peau et les muqueuses forment une première barrière. Quand un microbe la franchit, par exemple par une coupure, le système immunitaire réagit.",
    draw: a => `<rect x="30" y="180" width="440" height="30" fill="${C.mom}" opacity=".6"/>` + `<path d="M230 180 L250 230 L270 180" fill="${C.bg}"/>` + [0, 1, 2].map(i => bacterium(220 + i * 30, 140 - i * 10, .2, C.bad, { dna: false })).join('') + bacterium(250, 280, .25, C.bad, { dna: false }) + T(250, 110, 'microbes', { fs: 18, c: C.bad }) + T(90, 240, 'peau', { fs: 18 }) + T(250, 380, 'la barrière est franchie', { fs: 22, c: a }) },
  { say: "La première réponse est rapide, en quelques minutes à quelques heures, et elle est la même quel que soit le microbe : c'est l'immunité innée. Elle provoque une réaction inflammatoire, avec quatre signes : rougeur, chaleur, gonflement et douleur.",
    draw: a => `<circle cx="250" cy="230" r="120" fill="${C.bad}" fill-opacity=".25"/>` + ['rougeur', 'chaleur', 'gonflement', 'douleur'].map((t, i) => T(i % 2 ? 380 : 120, 150 + Math.floor(i / 2) * 170, t, { fs: 22, c: C.bad })).join('') + T(250, 238, 'inflammation', { fs: 24, w: 800 }) },
  { say: "Des cellules immunitaires arrivent alors sur place. Certaines, comme les macrophages, englobent les microbes et les digèrent : c'est la phagocytose. Elles libèrent aussi des messagers chimiques qui attirent d'autres cellules immunitaires.",
    draw: a => wbc(170, 240, 90, a) + bacterium(250, 230, .3, C.bad, { dna: false }) + bacterium(140, 220, .25, C.bad, { dna: false }) + T(170, 370, 'macrophage', { fs: 20 }) + T(360, 380, 'phagocytose', { fs: 22, c: a }) + bacterium(390, 200, .35, C.bad, { dna: false }) + arrow(360, 210, 270, 225, C.mut) },
  { sci: true, say: "En science : l'immunité innée est présente chez tous les animaux. Elle est immédiate, et peu spécifique. Elle se manifeste par la réaction inflammatoire aiguë, dont les symptômes sont la rougeur, la chaleur, le gonflement et la douleur. Des cellules comme les macrophages reconnaissent des motifs communs aux microbes, les phagocytent, et sécrètent des médiateurs chimiques de l'inflammation. Des médicaments anti-inflammatoires peuvent en réduire les symptômes.",
    rows: [['Immunité innée', 'immédiate, peu spécifique'], ['Inflammation', 'rougeur, chaleur, gonflement, douleur'], ['Phagocytose', 'macrophages : englobent et digèrent'], ['Médiateurs', 'messagers chimiques de l’inflammation']] }
 ]},
 { n: 2, title: "L'immunité adaptative", cues: [
  { say: "Chez les vertébrés, une deuxième réponse prend le relais, plus lente, environ une semaine, mais très précise : c'est l'immunité adaptative. Elle repose sur des globules blancs particuliers, les lymphocytes, capables de reconnaître un microbe bien précis.",
    draw: a => lineChart(60, 100, 360, 260, [[[0, .6, .7, .5, .3, .2, .1], C.T, 'innée'], [[0, 0, .1, .4, .8, .9, .7], a, 'adaptative']], { x: 'jours →', y: 'intensité' }) },
  { say: "Chaque lymphocyte possède un récepteur unique, qui reconnaît une seule molécule étrangère, appelée antigène. Quand un lymphocyte rencontre son antigène, il se multiplie beaucoup : c'est la sélection clonale.",
    draw: a => [0, 1, 2, 3].map(i => wbc(80 + i * 110, 150, 34, [C.T, C.G, a, C.C][i])).join('') + virus(300, 260, .5, C.bad) + T(370, 270, 'antigène', { fs: 18, c: C.bad, a: 'start' }) + arrow(300, 300, 300, 340, a) + [0, 1, 2, 3, 4].map(i => wbc(160 + i * 60, 400, 24, a)).join('') + T(250, 480, 'sélection clonale', { fs: 22, c: a }) },
  { say: "Il existe deux grandes familles de lymphocytes. Les lymphocytes B produisent des anticorps, des molécules en forme de Y, qui se fixent sur les antigènes et neutralisent les microbes. Les lymphocytes T tueurs, eux, détruisent les cellules infectées par un virus.",
    draw: a => wbc(110, 160, 50, C.T, 'lymphocyte B') + [0, 1, 2].map(i => antibody(210 + i * 40, 150 + i * 10, .7, C.T, 20)).join('') + virus(400, 160, .7, C.bad) + wbc(110, 360, 50, C.bad, 'lymphocyte T tueur') + cell(360, 360, 60, C.mut, virus(360, 360, .4, C.G)) + arrow(170, 360, 290, 360, C.bad) },
  { say: "Ces deux armées sont coordonnées par un troisième type de lymphocytes, les lymphocytes T auxiliaires, ou CD4. Ils stimulent la multiplication des lymphocytes B et T. C'est pour cela que le VIH, qui détruit ces cellules, affaiblit tout le système immunitaire.",
    draw: a => wbc(250, 140, 50, C.ok, 'T auxiliaire (CD4)') + arrow(220, 210, 140, 300, C.ok) + arrow(280, 210, 360, 300, C.ok) + wbc(120, 350, 40, C.T, 'B') + wbc(380, 350, 40, C.bad, 'T tueur') },
  { sci: true, say: "En science : l'immunité adaptative, propre aux vertébrés, est spécifique d'un antigène. Les lymphocytes porteurs du bon récepteur sont sélectionnés, se multiplient, puis se différencient. Les lymphocytes B deviennent des plasmocytes qui sécrètent des anticorps. Les anticorps se lient aux antigènes et forment des complexes immuns, éliminés par phagocytose. Les lymphocytes T CD8 deviennent cytotoxiques et détruisent les cellules infectées. Les lymphocytes T CD4 coordonnent ces réponses.",
    rows: [['Spécificité', 'un récepteur = un antigène'], ['Sélection clonale', 'multiplication du bon lymphocyte'], ['LB → plasmocytes', 'anticorps, complexes immuns'], ['LT CD8', 'détruisent les cellules infectées'], ['LT CD4', 'coordonnent (cible du VIH)']] }
 ]},
 { n: 3, title: 'Mémoire immunitaire et vaccination', cues: [
  { say: "Après une infection, certains lymphocytes restent dans le corps pendant des années : ce sont les lymphocytes mémoire. Ils sont plus nombreux et réagissent plus vite que les lymphocytes de départ.",
    draw: a => wbc(150, 230, 60, a, 'lymphocyte mémoire') + T(350, 210, 'plus nombreux', { fs: 22 }) + T(350, 250, 'plus rapides', { fs: 22 }) + T(350, 290, 'pendant des années', { fs: 22 }) },
  { say: "Si le même microbe revient, la réponse est donc beaucoup plus rapide et beaucoup plus forte. Souvent, on ne tombe même pas malade.",
    draw: a => lineChart(60, 100, 360, 260, [[[0, .05, .2, .35, .2, .1, .05, .1, .7, .95, .8, .6], a, '']], { x: 'temps →', y: 'anticorps' }) + T(130, 330, '1er contact', { fs: 17, c: C.mut }) + T(330, 120, '2e contact', { fs: 17, c: a }) },
  { say: "La vaccination utilise ce principe. On injecte un microbe tué, affaibli, ou seulement une partie de ce microbe, qui ne rend pas malade. Le corps fabrique alors des lymphocytes mémoire, prêts à réagir le jour où il rencontrera le vrai microbe.",
    draw: a => `<rect x="70" y="200" width="160" height="40" rx="10" fill="none" stroke="${C.ink}" stroke-width="4"/><rect x="230" y="212" width="80" height="16" fill="${C.ink}"/><rect x="80" y="208" width="80" height="24" fill="${a}" opacity=".7"/>` + T(150, 280, 'vaccin', { fs: 22 }) + arrow(330, 220, 380, 220, a) + wbc(430, 220, 36, a) + T(430, 290, 'mémoire', { fs: 18 }) },
  { say: "Quand une grande partie de la population est vaccinée, le microbe circule beaucoup moins. Les personnes qui ne peuvent pas être vaccinées, comme les nouveau-nés ou les malades, sont alors protégées elles aussi. C'est l'immunité collective.",
    draw: a => (() => { let s = ''; for (let i = 0; i < 20; i++) s += `<circle cx="${80 + (i % 5) * 85}" cy="${120 + Math.floor(i / 5) * 80}" r="22" fill="${[3, 11, 17].includes(i) ? C.T : a}" opacity="${[3, 11, 17].includes(i) ? 1 : .7}"/>`; return s; })() + T(250, 470, 'les vaccinés protègent les autres (jaune)', { fs: 19 }) },
  { sci: true, say: "En science : après un premier contact avec un antigène, des cellules mémoire persistent. Lors d'un second contact, la réponse secondaire est plus rapide, plus intense et plus durable. La vaccination déclenche une réponse primaire grâce à un antigène inoffensif, accompagné d'un adjuvant qui stimule l'immunité innée. Une couverture vaccinale élevée limite la circulation du pathogène et protège toute la population.",
    rows: [['Mémoire', 'lymphocytes mémoire durables'], ['Réponse secondaire', 'plus rapide, plus forte'], ['Vaccin', 'antigène inoffensif + adjuvant'], ['Immunité collective', 'protège aussi les non-vaccinés']] }
 ]}
]},
/* ---------- PREMIÈRE p05 : génétique et santé ---------- */
{ id: 'p05', level: 'premiere', ord: 4, title: 'Variation génétique et santé', clips: [
 { n: 1, title: 'La mucoviscidose, une maladie génétique', cues: [
  { say: "Rappel : chaque gène existe en deux exemplaires, un venant de chaque parent. Certaines maladies sont dues à un allèle muté d'un seul gène. C'est le cas de la mucoviscidose, la maladie génétique grave la plus fréquente en France.",
    draw: a => chromo(170, 240, C.mom, { h: 220, w: 34, single: true, band2: `<rect x="-17" y="10" width="34" height="22" fill="${C.ok}"/>` }) + chromo(330, 240, C.dad, { h: 220, w: 34, single: true, band2: `<rect x="-17" y="10" width="34" height="22" fill="${C.bad}"/>` }) + T(170, 390, 'allèle normal', { fs: 18, c: C.ok }) + T(330, 390, 'allèle muté', { fs: 18, c: C.bad }) },
  { say: "Le gène en cause, appelé CFTR, code une protéine qui fait passer des ions chlorure à travers la membrane des cellules. Quand elle ne fonctionne pas, le mucus qui tapisse les bronches et le tube digestif devient épais et collant.",
    draw: a => `<rect x="40" y="200" width="420" height="40" fill="${a}" opacity=".35"/>` + `<rect x="225" y="180" width="50" height="80" rx="10" fill="${C.ok}"/>` + T(250, 160, 'protéine CFTR', { fs: 20, c: C.ok }) + arrow(250, 300, 250, 260, C.T) + T(320, 310, 'ions chlorure', { fs: 18, c: C.T }) + T(250, 400, 'muté : mucus épais et collant', { fs: 21, c: C.bad }) },
  { say: "Ce mucus encombre les poumons, ce qui provoque des infections à répétition, et il gêne la digestion. Pour être malade, il faut avoir hérité de deux allèles mutés, un de chaque parent : on dit que l'allèle est récessif.",
    draw: a => T(250, 90, 'parents porteurs sains', { fs: 20, c: C.mut }) + [['N/m', 150], ['N/m', 350]].map(([g, x]) => person(x, 210, .9, C.T) + T(x, 320, g, { fs: 18 })).join('') + [['N/N', 70, C.ok], ['N/m', 190, C.T], ['N/m', 310, C.T], ['m/m', 430, C.bad]].map(([g, x, c]) => `<circle cx="${x}" cy="400" r="30" fill="${c}" opacity=".7"/>` + T(x, 460, g, { fs: 18 })).join('') + T(430, 500, 'malade : 1/4', { fs: 16, c: C.bad }) },
  { sci: true, say: "En science : la mucoviscidose est une maladie monogénique à transmission récessive. Elle est due à des mutations du gène CFTR, qui code un canal à ions chlorure. Le mucus déshydraté provoque des atteintes respiratoires et digestives. Les traitements associent kinésithérapie, antibiotiques, et désormais des médicaments qui corrigent le fonctionnement de la protéine. La thérapie génique est une piste de recherche.",
    rows: [['Gène', 'CFTR : canal à ions chlorure'], ['Transmission', 'récessive : 2 allèles mutés'], ['Symptômes', 'mucus épais : poumons, digestion'], ['Traitements', 'kiné, antibiotiques, correcteurs de la protéine']] }
 ]},
 { n: 2, title: 'Le cancer, une maladie des gènes', cues: [
  { say: "Rappel : les mutations somatiques se produisent dans les cellules du corps, et sont transmises à leurs cellules filles. Le cancer est une maladie qui commence ainsi, par des mutations dans une seule cellule.",
    draw: a => cell(250, 240, 90, a, `<circle cx="250" cy="240" r="24" fill="${C.bad}"/>`) + T(250, 380, 'une cellule mutée', { fs: 22, c: C.bad }) },
  { say: "Ces mutations touchent des gènes qui contrôlent la division cellulaire. Certains gènes sont comme un accélérateur bloqué, qui pousse la cellule à se diviser sans arrêt. D'autres sont comme des freins cassés, qui n'arrêtent plus la division.",
    draw: a => box(60, 140, 170, 90, 'accélérateur', C.bad, { fs: 20 }) + T(145, 260, 'bloqué', { fs: 18, c: C.bad }) + box(270, 140, 170, 90, 'frein', C.mut, { fs: 20 }) + T(355, 260, 'cassé', { fs: 18, c: C.bad }) + T(250, 360, 'division sans contrôle', { fs: 24, w: 800, c: C.bad }) },
  { say: "Il faut en général plusieurs mutations, accumulées au fil des années, pour qu'une cellule devienne cancéreuse. C'est pour cela que le risque augmente avec l'âge, et avec l'exposition à des agents mutagènes comme le tabac, l'alcool ou les UV.",
    draw: a => [0, 1, 2, 3].map(i => cell(80 + i * 115, 230, 44, a, [0, 1, 2, 3].slice(0, i + 1).map(j => `<circle cx="${70 + i * 115 + j * 8}" cy="${222 + j * 6}" r="6" fill="${C.bad}"/>`).join(''))).join('') + [0, 1, 2].map(i => arrow(128 + i * 115, 230, 150 + i * 115, 230)).join('') + T(250, 340, 'accumulation de mutations', { fs: 22 }) + T(250, 380, 'tabac, alcool, UV, âge', { fs: 20, c: C.mut }) },
  { sci: true, say: "En science : un cancer résulte de l'accumulation de mutations somatiques dans une lignée de cellules, qui se divisent alors de façon incontrôlée et forment une tumeur. Des facteurs environnementaux, comme le tabac, l'alcool, les UV ou certains virus, augmentent ce risque. La prévention, le dépistage précoce et des traitements ciblant les cellules cancéreuses améliorent la survie.",
    rows: [['Origine', 'mutations somatiques accumulées'], ['Gènes touchés', 'contrôle de la division cellulaire'], ['Facteurs de risque', 'tabac, alcool, UV, virus, âge'], ['Lutte', 'prévention, dépistage, traitements ciblés']] }
 ]},
 { n: 3, title: "La résistance aux antibiotiques", cues: [
  { say: "Rappel : les antibiotiques sont des médicaments qui tuent les bactéries ou empêchent leur multiplication. Mais dans une population de bactéries, quelques-unes peuvent porter, par hasard, une mutation qui les rend résistantes.",
    draw: a => [0, 1, 2, 3, 4, 5, 6, 7, 8].map(i => bacterium(100 + (i % 3) * 150, 130 + Math.floor(i / 3) * 100, .5, i === 4 ? C.bad : C.C, { dna: false })).join('') + T(250, 470, '1 bactérie résistante (mutation)', { fs: 20, c: C.bad }) },
  { say: "Quand on prend l'antibiotique, les bactéries sensibles meurent, mais les résistantes survivent et se multiplient. Peu à peu, toute la population devient résistante. C'est un exemple de sélection naturelle, que l'on peut observer en quelques jours.",
    draw: a => [0, 1, 2, 3, 4, 5, 6, 7, 8].map(i => bacterium(100 + (i % 3) * 150, 130 + Math.floor(i / 3) * 100, .5, C.bad, { dna: false })).join('') + T(250, 470, 'après traitement : toutes résistantes', { fs: 20, c: C.bad }) },
  { say: "Les bactéries peuvent aussi échanger leurs gènes de résistance, grâce aux plasmides. Pour limiter ce problème, il faut utiliser les antibiotiques seulement quand c'est nécessaire, et suivre le traitement jusqu'au bout.",
    draw: a => bacterium(140, 220, 1, C.bad, { plasmid: C.T }) + bacterium(360, 220, 1, C.C) + arrow(210, 220, 290, 220, C.T) + T(250, 350, 'règle : seulement si prescrit', { fs: 22, c: a }) },
  { sci: true, say: "En science : l'antibiorésistance résulte de la sélection, par l'antibiotique, de bactéries porteuses de mutations ou de gènes de résistance, acquis parfois par transfert horizontal. L'usage excessif ou inadapté des antibiotiques accélère ce phénomène. La lutte passe par un usage raisonné, l'hygiène, la vaccination et la recherche de nouveaux traitements.",
    rows: [['Origine', 'mutation ou gène reçu par plasmide'], ['Mécanisme', 'sélection par l’antibiotique'], ['Accélérée par', 'usage excessif ou inadapté'], ['Lutte', 'usage raisonné, hygiène, vaccins']] }
 ]}
]},
/* ---------- TERMINALE t04 : système nerveux ---------- */
{ id: 't04', level: 'terminale', ord: 10, title: 'Comportements, mouvement et système nerveux', clips: [
 { n: 1, title: 'Le réflexe myotatique', cues: [
  { say: "Quand un médecin tape sous ton genou avec un marteau, ta jambe se lève toute seule. C'est un réflexe : une réponse involontaire, rapide et toujours identique à un stimulus. Celui-ci s'appelle le réflexe myotatique, car il répond à l'étirement d'un muscle.",
    draw: a => `<path d="M200 80 V280 L330 400" stroke="${C.mut}" stroke-width="40" stroke-linecap="round" fill="none"/>` + `<rect x="120" y="270" width="60" height="18" rx="6" fill="${C.T}" transform="rotate(-20 150 280)"/>` + arrow(330, 400, 400, 330, a) + T(400, 460, 'la jambe se lève', { fs: 20, c: a }) },
  { say: "Voici le chemin du message. Le coup étire le muscle de la cuisse. Des récepteurs dans ce muscle envoient un message nerveux, par un neurone sensoriel, jusqu'à la moelle épinière.",
    draw: a => `<rect x="380" y="120" width="70" height="220" rx="30" fill="${C.mut}" opacity=".4"/>` + T(415, 370, 'moelle', { fs: 18 }) + `<ellipse cx="120" cy="250" rx="70" ry="120" fill="${C.bad}" fill-opacity=".3" stroke="${C.bad}" stroke-width="4"/>` + T(120, 400, 'muscle étiré', { fs: 18 }) + `<path d="M140 180 C 220 140, 320 150, 400 190" stroke="${C.dad}" stroke-width="6" fill="none"/>` + arrow(300, 152, 340, 160, C.dad) + T(260, 120, 'neurone sensoriel', { fs: 18, c: C.dad }) },
  { say: "Dans la moelle épinière, le neurone sensoriel transmet directement le message à un neurone moteur, au niveau d'une synapse. Le neurone moteur renvoie l'ordre au muscle, qui se contracte. Ce circuit s'appelle un arc réflexe.",
    draw: a => `<rect x="380" y="120" width="70" height="220" rx="30" fill="${C.mut}" opacity=".4"/>` + `<ellipse cx="120" cy="250" rx="70" ry="120" fill="${C.bad}" fill-opacity=".3" stroke="${C.bad}" stroke-width="4"/>` + `<path d="M140 180 C 220 140, 320 150, 400 190" stroke="${C.dad}" stroke-width="6" fill="none"/><path d="M400 210 C 320 300, 220 320, 150 300" stroke="${C.bad}" stroke-width="6" fill="none"/>` + `<circle cx="405" cy="200" r="10" fill="${C.T}"/>` + T(260, 360, 'neurone moteur', { fs: 18, c: C.bad }) + T(260, 120, 'neurone sensoriel', { fs: 18, c: C.dad }) + T(415, 90, 'synapse', { fs: 17, c: C.T }) },
  { sci: true, say: "En science : le réflexe myotatique est la contraction d'un muscle en réponse à son propre étirement. Son support est un arc réflexe monosynaptique : récepteur sensoriel du muscle, neurone sensoriel, centre nerveux, ici la moelle épinière, neurone moteur, et muscle effecteur. Il participe au maintien de la posture. Il est utilisé en médecine pour tester le fonctionnement du système nerveux.",
    rows: [['Réflexe', 'réponse involontaire et stéréotypée'], ['Arc réflexe', 'récepteur, neurone sensoriel, moelle, neurone moteur, muscle'], ['Monosynaptique', '1 seule synapse dans la moelle'], ['Rôle', 'posture ; test médical']] }
 ]},
 { n: 2, title: 'Le message nerveux et la synapse', cues: [
  { say: "Le message nerveux circule le long des neurones sous forme électrique. Il est codé par des potentiels d'action, de petites impulsions électriques, toujours de même taille. Plus le stimulus est fort, plus ils sont nombreux par seconde : c'est un codage en fréquence.",
    draw: a => T(40, 140, 'faible', { a: 'start', fs: 18, c: C.mut }) + `<path d="M120 160 H170 l5 -50 l5 50 H280 l5 -50 l5 50 H460" stroke="${a}" stroke-width="4" fill="none"/>` + T(40, 300, 'fort', { a: 'start', fs: 18, c: C.mut }) + `<path d="M120 320 ${[0, 1, 2, 3, 4, 5, 6].map(i => `H${150 + i * 45} l5 -50 l5 50`).join(' ')} H460" stroke="${C.bad}" stroke-width="4" fill="none"/>` + T(250, 420, 'codage en fréquence', { fs: 22, c: a }) },
  { say: "Entre deux neurones, il y a un petit espace : la synapse. Le message électrique ne peut pas le franchir. Au bout du premier neurone, il déclenche la libération de molécules chimiques, les neurotransmetteurs.",
    draw: a => `<path d="M40 160 H200 C 240 160, 250 200, 250 240 C 250 280, 240 320, 200 320 H40" fill="${C.T}" fill-opacity=".2" stroke="${C.T}" stroke-width="4"/><path d="M460 160 H310 C 290 200, 290 280, 310 320 H460" fill="${C.dad}" fill-opacity=".2" stroke="${C.dad}" stroke-width="4"/>` + [0, 1, 2, 3, 4, 5].map(i => `<circle cx="${262 + (i % 3) * 12}" cy="${210 + Math.floor(i / 3) * 40 + (i % 2) * 10}" r="5" fill="${C.ok}"/>`).join('') + T(280, 380, 'fente synaptique', { fs: 18 }) + T(250, 120, 'neurotransmetteurs', { fs: 18, c: C.ok }) },
  { say: "Ces neurotransmetteurs se fixent sur des récepteurs du neurone suivant, ou du muscle, et y font naître un nouveau message électrique. Au niveau du muscle, le neurotransmetteur est l'acétylcholine. La synapse est donc un relais chimique.",
    draw: a => `<path d="M40 160 H200 C 240 160, 250 200, 250 240 C 250 280, 240 320, 200 320 H40" fill="${C.T}" fill-opacity=".2" stroke="${C.T}" stroke-width="4"/><path d="M460 160 H310 C 290 200, 290 280, 310 320 H460" fill="${C.bad}" fill-opacity=".2" stroke="${C.bad}" stroke-width="4"/>` + [0, 1, 2].map(i => `<rect x="296" y="${190 + i * 40}" width="12" height="20" fill="${C.ok}"/><circle cx="290" cy="${200 + i * 40}" r="5" fill="${C.ok}"/>`).join('') + T(380, 380, 'muscle', { fs: 18 }) + T(250, 120, 'acétylcholine', { fs: 18, c: C.ok }) + T(250, 440, 'électrique → chimique → électrique', { fs: 19, c: a }) },
  { sci: true, say: "En science : le message nerveux est électrique le long des neurones, codé en fréquence de potentiels d'action. Au niveau des synapses, il devient chimique : des neurotransmetteurs, libérés dans la fente synaptique, se fixent sur des récepteurs de la cellule suivante. À la jonction entre neurone et muscle, la synapse neuromusculaire, le neurotransmetteur est l'acétylcholine. Certaines substances, comme le curare, peuvent bloquer ces récepteurs.",
    rows: [['Le long du neurone', 'électrique, codé en fréquence'], ['Synapse', 'relais chimique'], ['Neurotransmetteur', 'libéré, se fixe sur des récepteurs'], ['Neurone → muscle', 'acétylcholine'], ['Perturbateur', 'ex. curare']] }
 ]},
 { n: 3, title: 'Le mouvement volontaire et le cerveau', cues: [
  { say: "Contrairement au réflexe, un mouvement volontaire est décidé par le cerveau. La commande part d'une zone précise de la surface du cerveau, le cortex moteur. Le message descend ensuite par la moelle épinière jusqu'aux neurones moteurs.",
    draw: a => head(200, 230, 1.6, C.mut) + `<path d="M150 120 C 190 100, 230 100, 250 115" stroke="${a}" stroke-width="14" fill="none" stroke-linecap="round"/>` + T(330, 100, 'cortex moteur', { fs: 20, c: a, a: 'start', extra: 'dx="-20"' }) + arrow(200, 250, 200, 420, a) + T(220, 450, 'moelle épinière', { fs: 18, a: 'start' }) },
  { say: "Chaque partie du corps est commandée par une zone particulière du cortex moteur. Les zones qui commandent la main et la bouche sont très grandes, car ces parties font des mouvements fins et précis.",
    draw: a => `<path d="M110 400 A140 140 0 0 1 390 400" stroke="${C.mut}" stroke-width="40" fill="none"/>` + [['pied', 170], ['jambe', 145], ['tronc', 115], ['bras', 90], ['main', 64], ['bouche', 34]].map(([t, deg], i) => { const r = 196, x = 250 + r * Math.cos(deg * Math.PI / 180), y = 400 - r * Math.sin(deg * Math.PI / 180); return T(x, y + 6, t, { a: deg > 100 ? 'end' : deg < 80 ? 'start' : 'middle', fs: i > 3 ? 24 : 18, w: i > 3 ? 800 : 600, c: i > 3 ? a : C.ink }); }).join('') + T(250, 470, 'carte du corps sur le cortex', { fs: 19, c: C.mut }) },
  { say: "Le cerveau change avec l'apprentissage. Quand on s'entraîne, par exemple au piano ou au sport, les connexions entre neurones se renforcent, et la zone du cortex concernée s'agrandit. C'est la plasticité cérébrale. Elle permet aussi une récupération partielle après un accident.",
    draw: a => neuron(110, 180, .8, C.mut) + neuron(110, 330, .8, a) + `<line x1="300" y1="330" x2="420" y2="300" stroke="${a}" stroke-width="8"/><line x1="300" y1="330" x2="420" y2="360" stroke="${a}" stroke-width="8"/><line x1="300" y1="180" x2="420" y2="180" stroke="${C.mut}" stroke-width="3"/>` + T(380, 150, 'avant', { fs: 18, c: C.mut }) + T(380, 420, 'après entraînement', { fs: 18, c: a }) },
  { sci: true, say: "En science : le mouvement volontaire est commandé par les aires motrices du cortex cérébral. Les messages descendent par la moelle épinière jusqu'aux neurones moteurs, puis aux muscles. Le cortex moteur est organisé en une carte du corps, la somatotopie. La plasticité cérébrale, c'est-à-dire la capacité des réseaux de neurones à se remodeler, permet l'apprentissage et une récupération partielle après une lésion.",
    rows: [['Commande', 'cortex moteur → moelle → muscles'], ['Somatotopie', 'une zone du cortex par partie du corps'], ['Plasticité', 'les connexions se remodèlent'], ['Conséquences', 'apprentissage, récupération après lésion']] }
 ]}
]},
/* ---------- TERMINALE t05 : produire le mouvement ---------- */
{ id: 't05', level: 'terminale', ord: 11, title: 'Produire le mouvement : le muscle et son énergie', clips: [
 { n: 1, title: 'Du muscle aux protéines contractiles', cues: [
  { say: "Rappel : un mouvement est produit par la contraction d'un muscle, qui tire sur un os par l'intermédiaire d'un tendon. Mais comment un muscle se raccourcit-il ? Il faut zoomer, de plus en plus.",
    draw: a => `<rect x="60" y="200" width="380" height="20" rx="10" fill="${C.ink}" opacity=".5"/><ellipse cx="250" cy="160" rx="130" ry="50" fill="${C.bad}" fill-opacity=".4" stroke="${C.bad}" stroke-width="4"/>` + T(250, 260, 'os', { fs: 18, c: C.mut }) + T(250, 100, 'muscle', { fs: 20 }) + T(250, 360, 'zoom ↓', { fs: 22, c: a }) },
  { say: "Un muscle est fait de longues cellules, les fibres musculaires. Chacune contient des milliers de filaments, les myofibrilles, découpées en petites unités qui se répètent : les sarcomères.",
    draw: a => [0, 1, 2, 3].map(i => `<rect x="40" y="${120 + i * 50}" width="420" height="36" rx="18" fill="${C.bad}" fill-opacity=".3" stroke="${C.bad}" stroke-width="3"/>`).join('') + [0, 1, 2, 3, 4, 5].map(i => `<line x1="${70 + i * 70}" y1="120" x2="${70 + i * 70}" y2="306" stroke="${C.ink}" stroke-width="3"/>`).join('') + T(250, 360, 'sarcomère = unité de contraction', { fs: 21, c: a }) },
  { say: "Dans chaque sarcomère, deux sortes de filaments de protéines s'emboîtent : l'actine, fine, et la myosine, épaisse. Lors de la contraction, les têtes de myosine s'accrochent à l'actine et la tirent. Les filaments glissent les uns sur les autres, et le sarcomère raccourcit.",
    draw: a => [[140, 'repos', 130], [340, 'contracté', 90]].map(([y, t, half], k) => `<line x1="${250 - half - 30}" y1="${y - 40}" x2="${250 - half - 30}" y2="${y + 40}" stroke="${C.ink}" stroke-width="5"/><line x1="${250 + half + 30}" y1="${y - 40}" x2="${250 + half + 30}" y2="${y + 40}" stroke="${C.ink}" stroke-width="5"/>` + [-24, 0, 24].map(dy => `<line x1="${250 - half - 30}" y1="${y + dy - 12}" x2="${250 - 20 + (k ? 0 : -30)}" y2="${y + dy - 12}" stroke="${C.T}" stroke-width="4"/><line x1="${250 + half + 30}" y1="${y + dy - 12}" x2="${250 + 20 - (k ? 0 : -30)}" y2="${y + dy - 12}" stroke="${C.T}" stroke-width="4"/><line x1="${250 - 80}" y1="${y + dy}" x2="${250 + 80}" y2="${y + dy}" stroke="${C.G}" stroke-width="8"/>`).join('') + T(250, y + 75, t, { fs: 18, c: C.mut })).join('') + T(80, 80, 'actine', { fs: 17, c: C.T }) + T(400, 80, 'myosine', { fs: 17, c: C.G }) },
  { sci: true, say: "En science : la contraction musculaire repose sur le glissement des filaments d'actine le long des filaments de myosine, dans chaque sarcomère. Ce glissement est déclenché par l'arrivée de calcium dans la cellule, à la suite du message nerveux, et il consomme de l'ATP. Le raccourcissement de milliers de sarcomères produit le raccourcissement du muscle.",
    rows: [['Muscle', 'fibres → myofibrilles → sarcomères'], ['Protéines', 'actine (fine), myosine (épaisse)'], ['Mécanisme', 'glissement des filaments'], ['Déclencheur', 'calcium, suite au message nerveux'], ['Énergie', 'consomme de l’ATP']] }
 ]},
 { n: 2, title: "L'ATP, la monnaie d'énergie", cues: [
  { say: "Pour se contracter, la myosine a besoin d'énergie. Cette énergie est fournie par une molécule, l'ATP. On peut la comparer à une pile rechargeable : quand elle est utilisée, elle devient de l'ADP, puis elle est rechargée en ATP.",
    draw: a => `<rect x="80" y="160" width="130" height="70" rx="12" fill="${C.ok}"/><rect x="210" y="180" width="14" height="30" fill="${C.ok}"/>` + T(145, 205, 'ATP', { fs: 26, w: 800, c: '#0F1417' }) + `<rect x="290" y="160" width="130" height="70" rx="12" fill="none" stroke="${C.mut}" stroke-width="4"/><rect x="420" y="180" width="14" height="30" fill="${C.mut}"/>` + T(355, 205, 'ADP', { fs: 26, w: 800, c: C.mut }) + arrow(215, 140, 300, 140, C.bad) + T(255, 120, 'énergie utilisée', { fs: 16, c: C.bad }) + arrow(300, 260, 215, 260, C.ok) + T(255, 290, 'rechargée', { fs: 16, c: C.ok }) },
  { say: "Le muscle ne contient qu'un tout petit stock d'ATP, de quoi tenir quelques secondes. Il doit donc en refabriquer en permanence, à partir des nutriments, surtout le glucose.",
    draw: a => bars(80, 100, 340, 260, [['stock', 1, C.mut], ['besoin', 10, C.bad]], { val: () => '' }) + T(165, 400, 'quelques secondes', { fs: 17, c: C.mut }) + T(335, 400, 'en continu', { fs: 17, c: C.bad }) },
  { say: "Deux voies permettent de recharger l'ATP. La respiration, dans les mitochondries, utilise du dioxygène : elle produit beaucoup d'ATP, et rejette du dioxyde de carbone et de l'eau. La fermentation, sans dioxygène, est rapide mais produit peu d'ATP, et elle produit de l'acide lactique.",
    draw: a => box(40, 100, 200, 220, '', C.ok) + T(140, 140, 'respiration', { fs: 21, c: C.ok }) + mito(140, 200, .8) + T(140, 260, 'avec O₂', { fs: 17 }) + T(140, 295, '≈ 32 ATP', { fs: 22, w: 800 }) + box(260, 100, 200, 220, '', C.T) + T(360, 140, 'fermentation', { fs: 21, c: C.T }) + T(360, 220, 'sans O₂', { fs: 17 }) + T(360, 260, '→ acide lactique', { fs: 17 }) + T(360, 295, '2 ATP', { fs: 22, w: 800 }) + T(250, 380, 'par molécule de glucose', { fs: 18, c: C.mut }) },
  { sci: true, say: "En science : l'ATP est la molécule qui fournit directement l'énergie de la contraction. Elle est régénérée en permanence à partir des métabolites, comme le glucose. La respiration cellulaire, dans le cytoplasme puis la mitochondrie, oxyde complètement le glucose grâce au dioxygène et produit beaucoup d'ATP. La fermentation lactique, en absence suffisante de dioxygène, produit peu d'ATP. Les deux voies commencent par la glycolyse.",
    rows: [['ATP', 'source directe d’énergie'], ['Respiration', 'O₂, mitochondrie, beaucoup d’ATP'], ['Fermentation lactique', 'sans O₂, peu d’ATP'], ['Point commun', 'glycolyse du glucose']] }
 ]},
 { n: 3, title: "L'effort et le contrôle de la glycémie", cues: [
  { say: "Pendant un effort, les muscles consomment beaucoup de glucose. Pourtant, la quantité de glucose dans le sang, la glycémie, reste stable, autour d'un gramme par litre. Le corps la régule en permanence.",
    draw: a => lineChart(60, 100, 360, 240, [[[.5, .52, .48, .5, .51, .49, .5], a, '1 g/L']], { x: 'temps →', y: 'glycémie' }) },
  { say: "Le glucose est stocké sous forme de glycogène, dans le foie et dans les muscles. Quand la glycémie baisse, le foie libère du glucose dans le sang. Après un repas, au contraire, le glucose en trop est mis en réserve.",
    draw: a => `<path d="M120 160 C 120 100, 300 90, 360 140 C 390 180, 330 230, 250 230 C 170 230, 120 210, 120 160Z" fill="${C.bad}" fill-opacity=".4" stroke="${C.bad}" stroke-width="4"/>` + T(240, 175, 'foie : glycogène', { fs: 20 }) + arrow(200, 250, 200, 330, a) + T(150, 300, 'libère', { fs: 17, c: a }) + arrow(300, 330, 300, 250, C.ok) + T(360, 300, 'stocke', { fs: 17, c: C.ok }) + `<rect x="60" y="340" width="380" height="40" rx="20" fill="${C.bad}" opacity=".3"/>` + T(250, 367, 'sang', { fs: 18 }) },
  { say: "Ce sont deux hormones du pancréas qui donnent les ordres. L'insuline fait baisser la glycémie, en favorisant le stockage. Le glucagon fait monter la glycémie, en provoquant la libération du glucose par le foie.",
    draw: a => box(170, 80, 160, 60, 'pancréas', a) + arrow(210, 150, 120, 240, C.dad) + arrow(290, 150, 380, 240, C.T) + pill(120, 270, 150, 'insuline', C.dad) + pill(380, 270, 150, 'glucagon', C.T) + T(120, 330, 'glycémie ↓', { fs: 20 }) + T(380, 330, 'glycémie ↑', { fs: 20 }) },
  { sci: true, say: "En science : la glycémie est maintenue autour d'un gramme par litre. Le glucose est stocké sous forme de glycogène dans le foie et les muscles. Le pancréas sécrète l'insuline, hormone hypoglycémiante, et le glucagon, hormone hyperglycémiante. Pendant un effort, l'apport en glucose et en dioxygène aux muscles augmente, grâce à l'adaptation de la respiration, du rythme cardiaque et de cette régulation hormonale.",
    rows: [['Glycémie', '≈ 1 g/L, régulée'], ['Réserves', 'glycogène : foie et muscles'], ['Insuline', 'fait baisser la glycémie'], ['Glucagon', 'fait monter la glycémie'], ['À l’effort', 'plus de glucose et d’O₂ aux muscles']] }
 ]}
]},
/* ---------- TERMINALE t06 : stress ---------- */
{ id: 't06', level: 'terminale', ord: 12, title: 'Comportements et stress', clips: [
 { n: 1, title: 'La réponse au stress aigu', cues: [
  { say: "Imagine qu'un chien surgit en aboyant. En une fraction de seconde, ton cœur s'accélère, ta respiration aussi, et tes muscles se préparent à fuir. C'est la réponse de stress : elle prépare le corps à faire face à un danger.",
    draw: a => person(160, 280, 1.6, C.mut) + `<path d="M380 180 L460 330 H300Z" fill="none" stroke="${C.T}" stroke-width="8" stroke-linejoin="round"/>` + T(380, 315, '!', { fs: 70, w: 800, c: C.T }) + T(250, 480, 'un danger : le stress', { fs: 22, c: a }) },
  { say: "La réponse se fait en deux temps. D'abord, très vite, le système nerveux fait libérer de l'adrénaline par les glandes surrénales, situées au-dessus des reins. L'adrénaline augmente le rythme cardiaque et libère du glucose pour les muscles.",
    draw: a => head(250, 120, .7, C.mut) + arrow(250, 200, 250, 280, a) + `<ellipse cx="200" cy="360" rx="36" ry="50" fill="${C.bad}" opacity=".5"/><ellipse cx="300" cy="360" rx="36" ry="50" fill="${C.bad}" opacity=".5"/><path d="M180 310 Q200 290 220 310" fill="${C.T}"/><path d="M280 310 Q300 290 320 310" fill="${C.T}"/>` + pill(250, 450, 180, 'adrénaline', C.T) + T(400, 330, 'surrénales', { fs: 17, a: 'start', extra: 'dx="-40"' }) },
  { say: "Ensuite, en quelques minutes, une deuxième hormone prend le relais : le cortisol. Sa sécrétion est commandée par le cerveau, via l'hypothalamus et l'hypophyse. Le cortisol maintient un apport élevé de glucose, pour tenir dans la durée.",
    draw: a => box(150, 70, 200, 56, 'hypothalamus', a) + arrow(250, 130, 250, 170) + box(150, 175, 200, 56, 'hypophyse', a) + arrow(250, 235, 250, 275) + box(150, 280, 200, 56, 'surrénales', C.bad) + arrow(250, 340, 250, 380) + pill(250, 410, 160, 'cortisol', C.T) },
  { sci: true, say: "En science : le stress aigu est une réponse adaptative de l'organisme. Une première phase, très rapide, met en jeu le système nerveux et l'adrénaline sécrétée par la médullosurrénale. Une seconde phase met en jeu l'axe hypothalamo-hypophyso-corticosurrénalien, qui aboutit à la sécrétion de cortisol. Ces hormones augmentent la disponibilité du glucose et l'activité cardiovasculaire.",
    rows: [['Stress aigu', 'réponse adaptative à un danger'], ['Phase 1', 'nerfs + adrénaline, en secondes'], ['Phase 2', 'axe hypothalamus → hypophyse → surrénales'], ['Cortisol', 'glucose disponible dans la durée']] }
 ]},
 { n: 2, title: 'Le retour au calme', cues: [
  { say: "Une fois le danger passé, le corps doit revenir à la normale. C'est le cortisol lui-même qui déclenche ce retour au calme.",
    draw: a => lineChart(60, 100, 360, 240, [[[.2, .9, .8, .5, .3, .2, .2], C.T, 'cortisol']], { x: 'temps →', y: 'concentration' }) },
  { say: "Quand le cortisol est abondant dans le sang, il agit sur l'hypothalamus et l'hypophyse, et freine leur activité. La production de cortisol diminue donc. On appelle cela un rétrocontrôle négatif : le produit final freine sa propre fabrication.",
    draw: a => box(150, 70, 200, 56, 'hypothalamus', a) + arrow(250, 130, 250, 170) + box(150, 175, 200, 56, 'hypophyse', a) + arrow(250, 235, 250, 275) + box(150, 280, 200, 56, 'surrénales', C.bad) + pill(250, 400, 160, 'cortisol', C.T) + `<path d="M330 400 C 450 400, 450 100, 355 98" stroke="${C.bad}" stroke-width="5" fill="none" stroke-dasharray="10 6"/>` + T(450, 250, '–', { fs: 50, w: 800, c: C.bad }) },
  { say: "Ce système fonctionne comme un thermostat. Il permet de répondre fortement à un danger, puis de revenir à l'équilibre. Le cerveau, notamment l'hippocampe, participe aussi à ce freinage.",
    draw: a => `<circle cx="250" cy="240" r="110" fill="none" stroke="${a}" stroke-width="10"/><line x1="250" y1="240" x2="320" y2="180" stroke="${C.ink}" stroke-width="8" stroke-linecap="round"/>` + T(250, 400, 'comme un thermostat', { fs: 22, c: a }) },
  { sci: true, say: "En science : la sécrétion de cortisol est régulée par un rétrocontrôle négatif. Le cortisol inhibe l'hypothalamus et l'hypophyse, ce qui limite sa propre sécrétion. Des structures cérébrales comme l'hippocampe participent à ce contrôle. Cette régulation permet un retour à l'état initial après la réponse au stress : c'est la résilience de l'organisme.",
    rows: [['Rétrocontrôle négatif', 'le cortisol freine sa propre production'], ['Cibles', 'hypothalamus, hypophyse'], ['Hippocampe', 'participe au freinage'], ['Résultat', 'retour à l’équilibre']] }
 ]},
 { n: 3, title: 'Quand le stress devient chronique', cues: [
  { say: "Si le stress dure des semaines ou des mois, par exemple à cause d'une pression permanente, le système de freinage s'épuise. Le cortisol reste élevé trop longtemps.",
    draw: a => lineChart(60, 100, 360, 240, [[[.3, .8, .75, .8, .78, .82, .8], C.bad, 'cortisol']], { x: 'semaines →', y: 'concentration' }) },
  { say: "Cela a des effets négatifs : fatigue, troubles du sommeil, anxiété, baisse des défenses immunitaires, et même des modifications de certains neurones du cerveau, notamment dans l'hippocampe.",
    draw: a => ['fatigue', 'sommeil perturbé', 'anxiété', 'immunité affaiblie', 'neurones modifiés'].map((t, i) => `<circle cx="80" cy="${110 + i * 70}" r="12" fill="${C.bad}"/>` + T(110, 117 + i * 70, t, { a: 'start', fs: 22 })).join('') },
  { say: "Heureusement, on peut agir. Une activité physique régulière, un bon sommeil, la relaxation et le soutien des autres aident à mieux gérer le stress. Dans certains cas, des médicaments, comme les anxiolytiques, peuvent être prescrits, mais ils ont des effets secondaires et peuvent créer une dépendance.",
    draw: a => ['activité physique', 'sommeil', 'relaxation', 'soutien social'].map((t, i) => box(60 + (i % 2) * 200, 110 + Math.floor(i / 2) * 120, 180, 80, t, C.ok, { fs: 19 })).join('') + T(250, 420, 'médicaments : sur prescription', { fs: 19, c: C.mut }) },
  { sci: true, say: "En science : un stress chronique provoque une sécrétion prolongée de cortisol et un dérèglement de son rétrocontrôle. Il peut altérer le fonctionnement du système nerveux, notamment l'hippocampe, et du système immunitaire. Des approches comme l'activité physique, la relaxation et le sommeil limitent ses effets. Des molécules anxiolytiques, comme les benzodiazépines, agissent sur les synapses, mais exposent à des effets secondaires et à une dépendance.",
    rows: [['Stress chronique', 'cortisol élevé longtemps'], ['Effets', 'sommeil, anxiété, immunité, hippocampe'], ['Prévention', 'sport, sommeil, relaxation, entourage'], ['Médicaments', 'anxiolytiques : dépendance possible']] }
 ]}
]}
);
